	return age !== null && age >= STALE_EXPOSURE_DAYS && remainingDays > 1;
}

/** 지금 화면과 규칙이 고르는 글 하나의 제안. 입력 순서를 유지한다. */
export function proposeBatch(
	listings: Listing[],
	rules: RuleSet,
	today = seoulToday(),
	now: Clock = Date.now(),
): Proposal[] {
	const bumping = bumpingIds(listings, rules, today, now);

	return listings.map((listing) => {
		const scheduled = scheduleFor(listing, today);
		const base = {
			id: listing.id,
			price: scheduled.price,
			priceChanged: scheduled.changed,
			ratio: scheduled.ratio,
			nextBumpAt: listing.nextBumpAt,
		};

		if (!listing.included) {
			return { ...base, action: "skip" as const, skipReason: "excluded" as const, blocked: null, note: null };
		}

		// 예약중 글은 거래 약속이 잡혀 있다. 끌올도 가격 인하도 하지 않는다.
		if (listing.reserved) {
			return { ...base, action: "skip" as const, skipReason: "reserved" as const, blocked: null, note: null };
		}

		if (bumping.has(listing.id)) {
			return {
				...base,
				action: "bump" as const,
				skipReason: null,
				blocked: null,
				note: scheduled.changed ? null : scheduled.remainingDays > 0 ? ("floor-reached" as const) : null,
			};
		}

		// 끌올하지 못하는 글도 가격은 날마다 직선을 따라 내린다. 쿨타임이 풀릴 때까지 인하를 미루면 풀린 날 몰아서 내리게 된다.
		const blocked: Blocked = blockedBy(listing, now) ?? "daily-limit";
		if (scheduled.changed && !holdsCutForBump(listing, blocked, scheduled.remainingDays)) {
			return { ...base, action: "price-only" as const, skipReason: null, blocked, note: null };
		}
		return { ...base, action: "skip" as const, skipReason: blocked, blocked, note: null };
	});
}

export function summarize(proposals: Proposal[]): ProposalSummary {
	return proposals.reduce<ProposalSummary>(
		(summary, proposal) => {
			if (proposal.action === "skip") summary.skip += 1;
			else if (proposal.action === "bump") summary.bump += 1;
			else summary.priceOnly += 1;
			if (proposal.blocked === "daily-limit") summary.held += 1;
