export function guardSnapshot(approved: ApprovedSnapshot, current: CurrentSnapshot): SnapshotVerdict {
	const observed = { ...current };
	if (current.price !== approved.price) {
		return { run: false, skipReason: "price-changed", observed, numbersMovedOnly: false };
	}
	const numbersMovedOnly =
		current.views !== approved.views || current.chats !== approved.chats || current.hearts !== approved.hearts;
	return { run: true, skipReason: null, observed, numbersMovedOnly };
}

